import { NextResponse } from "next/server";
import { z } from "zod";
import { createServerSupabase } from "@/lib/supabase/server";
import { createAdminClient } from "@/lib/supabase/admin";
const patchSchema=z.object({name:z.string().trim().min(1).max(80).optional(),description:z.string().trim().max(200).nullable().optional(),category:z.string().trim().max(60).nullable().optional(),price:z.number().min(.5).max(50000).optional(),imagePath:z.string().max(600).nullable().optional(),isAvailable:z.boolean().optional(),sortOrder:z.number().int().min(0).max(100000).optional()}).refine(v=>Object.keys(v).length>0);
async function owned(request:Request,id:string){const supabase=await createServerSupabase();const {data:{user}}=await supabase.auth.getUser();if(!user)return {error:"Please log in.",status:401 as const};const db=createAdminClient();const {data:vendor}=await db.from("vendors").select("id,is_active").eq("owner_id",user.id).single();if(!vendor)return {error:"Shop not found.",status:404 as const};if(!vendor.is_active)return {error:"Pay the setup fee before managing products.",status:403 as const};const {data:product}=await db.from("products").select("id,vendor_id,image_path").eq("id",id).eq("vendor_id",vendor.id).maybeSingle();if(!product)return {error:"Product not found.",status:404 as const};return {db,vendor,product};}
export async function PATCH(request:Request,{params}:{params:Promise<{id:string}>}){try{const {id}=await params;const ctx=await owned(request,id);if("error" in ctx)return NextResponse.json({error:ctx.error},{status:ctx.status});const parsed=patchSchema.safeParse(await request.json());if(!parsed.success)return NextResponse.json({error:"Check the product details."},{status:400});const v=parsed.data;if(v.imagePath&&(!v.imagePath.startsWith(`${ctx.vendor.id}/products/`)||!/^[a-z0-9-]+\.webp$/.test(v.imagePath.split("/").at(-1)||"")))return NextResponse.json({error:"Choose a product photo uploaded to your shop."},{status:400});const update:Record<string,unknown>={};if(v.name!==undefined)update.name=v.name;if(v.description!==undefined)update.description=v.description;if(v.category!==undefined)update.category=v.category;if(v.price!==undefined)update.price=Math.round(v.price*100)/100;if(v.imagePath!==undefined)update.image_path=v.imagePath;if(v.isAvailable!==undefined)update.is_available=v.isAvailable;if(v.sortOrder!==undefined)update.sort_order=v.sortOrder;update.updated_at=new Date().toISOString();const {data,error}=await ctx.db.from("products").update(update).eq("id",ctx.product.id).eq("vendor_id",ctx.vendor.id).select("id,name,description,category,price,image_path,is_available,sort_order,created_at,updated_at").single();if(error)throw error;return NextResponse.json({product:data});}catch{return NextResponse.json({error:"Product could not be updated."},{status:400});}}
export async function DELETE(request:Request,{params}:{params:Promise<{id:string}>}){try{const {id}=await params;const ctx=await owned(request,id);if("error" in ctx)return NextResponse.json({error:ctx.error},{status:ctx.status});const {error}=await ctx.db.from("products").delete().eq("id",ctx.product.id).eq("vendor_id",ctx.vendor.id);if(error)throw error;if(ctx.product.image_path?.startsWith(`${ctx.vendor.id}/products/`)){await ctx.db.storage.from("shop-media").remove([ctx.product.image_path]);}return NextResponse.json({success:true});}catch{return NextResponse.json({error:"Product could not be deleted."},{status:400});}}
